contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address account, uint256 id, uint256 readSeed) public payable {
        require(account != address(0), "ERC1155 view requires nonzero owner");

        uint256 beforeBalance = c.balanceOf(account, id); if (__ESBMC_reverted()) return;
        uint256 tsBefore = block.timestamp;
        uint256 readValue = c.balanceOf(account, id); if (__ESBMC_reverted()) return;
        uint256 tsAfter = block.timestamp;

        assert(readValue == beforeBalance && tsAfter == tsBefore);
    }
}

