contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(address account, uint256 id, uint256 readSeed) internal {
        vm.assume(account != address(0));
        uint256 beforeBalance;
        try c.balanceOf(account, id) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        uint256 tsBefore = block.timestamp;
        uint256 readValue;
        try c.balanceOf(account, id) returns (uint256 __r) { readValue = __r; } catch { return; }
        uint256 tsAfter = block.timestamp;
        assertTrue(readValue == beforeBalance && tsAfter == tsBefore);
    }

    function testFuzz_run(address account, uint256 id, uint256 readSeed) public {
